typedef long long ll;

struct BIT {
    int sz;
    vector<ll> data;

    BIT(int n) : sz(n), data(n + 1) {}

    void add(int idx, ll val) {
        for (++idx; idx <= sz; idx += idx & -idx)
            data[idx] += val;
    }

    ll query(int idx) {
        ll res = 0;
        for (++idx; idx > 0; idx -= idx & -idx)
            res += data[idx];
        return res;
    }
};

