        }
        for(int j = 0; j < len; ++j){
            bit.add(pos[a[j]], -1);
            inversions -= len - 1 - pos[a[j]] - bit.query(pos[a[j]]);
            pos[a[j]] = j;
            inversions += pos[a[j]] - bit.query(pos[a[j]]);
            bit.add(pos[a[j]], 1);
        }
    }
    for(int i = m - 1; i >= 0; --i){
        printf("%lld\n", ans[i]);
    }
}

