                int newMask = mask;
                char c = grid[nx][ny];
                if(c != 'T'){
                    newMask |= (1 << (c - 'a'));
                }
                int cnt = __builtin_popcount(newMask);

                if(cnt <= k && !visited[nx][ny][newMask]){
                    visited[nx][ny][newMask] = true;
                    vector<char> newPath = path;
                    if(c != 'T'){
                        newPath.push_back(c);
                    }
                    pq.emplace(dist + 1, nx, ny, newMask, newPath);
                }
            }
        }
    }
    cout << "-1";
}

