const int MAXN = 1e5 + 10;
multiset<int> S;
int medians[MAXN];
int med_cnt = 0;

int find_median(multiset<int>::iterator &it) {
    auto start = it;
    advance(start, -2);
    return *next(start, 2);
}

void update_medians() {
    med_cnt = 0;
    for (auto it = S.begin(); it != S.end(); ) {
        medians[med_cnt++] = find_median(it);
        advance(it, 5);
    }
}

long long sum_of_medians() {
    long long sum = 0;
    for (int i = 0; i < med_cnt; ++i) {
        sum += medians[i];
    }
    return sum;
}

