        string op;
        cin >> op;
        if (op == "add") {
            int x;
            cin >> x;
            auto it = S.insert(x);
            if (it == S.begin() || *prev(it) != x) {
                update_medians();
            }
        } else if (op == "del") {
            int x;
            cin >> x;
            auto it = S.find(x);
            if (it != S.end()) {
                S.erase(it);
                if (it == S.begin() || *prev(it) != x) {
                    update_medians();
                }
            }
        } else {
            if (S.empty()) {
                cout << 0 << "\n";
            } else {
                cout << sum_of_medians() << "\n";
            }
        }
    }
    return 0;
}

