using namespace std;

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

struct State {
    int x, y, mask, dist;
    State(int _x, int _y, int _mask, int _dist) : x(_x), y(_y), mask(_mask), dist(_dist) {}
};

int main(){
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> grid(H);
    int start_x = -1, start_y = -1, end_x = -1, end_y = -1;
    vector<pair<int, int>> apples;
    for(int i=0; i<H; ++i){
        cin >> grid[i];
        for(int j=0; j<W; ++j){
            if(grid[i][j] == 's'){
                start_x = i;
                start_y = j;
            }
            if(grid[i][j] == 'e'){
                end_x = i;
                end_y = j;
            }
            if(grid[i][j] == 'a'){
                apples.push_back({i, j});
            }
        }
    }

    int total_apples = apples.size();
    int target_mask = (1 << total_apples) - 1;
    vector<vector<vector<bool>>> visited(H, vector<vector<bool>>(W, vector<bool>(1 << total_apples, false)));
    queue<State> q;
    q.emplace(start_x, start_y, 0, 0);
    visited[start_x][start_y][0] = true;

    while(!q.empty()){
        auto [x, y, mask, dist] = q.front();
        q.pop();

        if(x == end_x && y == end_y && mask == target_mask){
            cout << dist << "\n";
            return 0;
        }

        for(int i=0; i<4; ++i){
            int nx = x + dx[i];
            int ny = y + dy[i];
            if(nx < 0 || nx >= H || ny < 0 || ny >= W || grid[nx][ny] == '#'){
                continue;
            }
            int new_mask = mask;
            for(int j=0; j<total_apples; ++j){
                if(apples[j].first == nx && apples[j].second == ny && !(mask & (1 << j))){
                    new_mask |= (1 << j);
                    break;
                }
            }
            if(!visited[nx][ny][new_mask]){
                visited[nx][ny][new_mask] = true;
                q.emplace(nx, ny, new_mask, dist + 1);
            }
        }
    }

    cout << "-1\n";
}

#include <bits/stdc++.h>
using namespace std;

const int MAX_V = 105;
const int INF = 1e9;

struct Edge {
    int from, to, cost;
};

int V, E, root;
vector<Edge> edges;

int seen[MAX_V], low[MAX_V], scc[MAX_V], label, num_scc;
stack<int> S;
vector<int> G[MAX_V], rG[MAX_V];
int dp[MAX_V][MAX_V];

int add_edge(int from, int to, int cost) {
    edges.push_back((Edge){from, to, cost});
    return edges.size() - 1;
}

void dfs(int v) {
    seen[v] = 1;
    low[v] = label++;
    S.push(v);
    for (auto &e : G[v]) {
        if (!seen[e]) {
            dfs(e);
            low[v] = min(low[v], low[e]);
        } else if (!scc[e]) {
            low[v] = min(low[v], low[e]);
        }
    }

    if (low[v] == seen[v]) {
        while (1) {
            int u = S.top(); S.pop();
            scc[u] = num_scc;
            if (u == v) break;
        }
        num_scc++;
    }
}

void init_scc() {
    memset(seen, 0, sizeof(seen));
    memset(scc, 0, sizeof(scc));
    label = num_scc = 0;
    while (!S.empty()) S.pop();

    for (int i = 0; i < V; i++) {
        if (!seen[i]) dfs(i);
    }

    for (int i = 0; i < V; i++) {
        rG[i].clear();
        for (auto &e : G[e.from]) {
            if (scc[e.from] == scc[e.to]) continue;
            rG[scc[e.from]].push_back(scc[e.to]);
        }
    }
}

int solve() {
    init_scc();
    int new_V = num_scc;

    for (int i = 0; i < new_V; i++) {
        for (int j = 0; j < new_V; j++) {
            dp[i][j] = (i == j) ? 0 : INF;
        }
    }

    for (auto &e : edges) {
        int from_scc = scc[e.from];
        int to_scc = scc[e.to];
        dp[from_scc][to_scc] = min(dp[from_scc][to_scc], e.cost);
    }

    int root_scc = scc[root];

    for (int k = 0; k < new_V; k++) {
        for (int i = 0; i < new_V; i++) {
            for (int j = 0; j < new_V; j++) {
                if (dp[i][j] > dp[i][k] + dp[k][j]) {
                    dp[i][j] = dp[i][k] + dp[k][j];
                }
            }
        }
    }

    int min_cost = 0;
    for (int i = 0; i < new_V; i++) {
        if (i == root_scc) continue;
        if (dp[root_scc][i] >= INF) return -1; // No such arborescence
        min_cost += dp[root_scc][i];
    }

    return min_cost;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> V >> E >> root;

    for (int i = 0; i < V; i++) {
        G[i].clear();
    }
    edges.clear();

    for (int i = 0; i < E; i++) {
        int s, t, w;
        cin >> s >> t >> w;
        add_edge(s, t, w);
        G[s].push_back(i);
    }

    cout << solve() << "\n";

    return 0;
}

