#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int N = 505;
const int MOD = 998244353;

int n, k;
int dp[N][2];

bool check(int a, int b) {
    int cnt = 0;
    while (a && b) {
        if ((a & 1) == (b & 1)) cnt++;
        else cnt = 0;
        if (cnt >= k) return false;
        a >>= 1; b >>= 1;
    }
    return true;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    if(n == 1 && k == 1){
        cout << 0;
        return 0;
    }
    int m = 1 << n;
    for(int i=0; i<m; i++) dp[i][0] = 1;
    for(int i=0; i<n; i++){
        for(int j=0; j<m; j++){
            if(dp[j][i%2] == 0) continue;
            int last = i == 0 ? 0 : j;
            dp[j][i%2^1] = 0;
            for(int k=0; k<m; k++){
                if(check(j, k) && check(last, k)){
                    dp[j][i%2^1] = (dp[j][i%2^1] + dp[k][i%2]) % MOD;
                }
            }
        }
    }
    int res = 0;
    for(int i=0; i<m; i++){
        res = (res + dp[i][n%2^1]) % MOD;
    }
    cout << res;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef double db;
const int MAXN = 100005;

int n, q;
db p[MAXN];
vector<int> adj[MAXN];
db exp_kingdoms[MAXN];

db dfs(int u, int par) {
    db sum = p[u];
    for (int v : adj[u]) {
        if (v == par) continue;
        sum += dfs(v, u);
    }
    exp_kingdoms[u] = sum;
    return sum;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    for(int i = 0; i < n; i++) cin >> p[i];
    for(int i =0; i < n-1; i++){
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    dfs(0, -1);
    db total_exp = 0.0;
    for(int i =0; i < n; i++) total_exp += exp_kingdoms[i] * (1.0 - p[i]);
    cin >> q;
    while(q--){
        int u;
        db np;
        cin >> u >> np;
        total_exp -= exp_kingdoms[u] * (1.0 - p[u]);
        p[u] = np;
        db new_sum = p[u];
        for(int v : adj[u]){
            new_sum += exp_kingdoms[v];
        }
        total_exp += new_sum * (1.0 - p[u]);
        exp_kingdoms[u] = new_sum;
        cout << fixed << setprecision(5) << total_exp << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <random>
#include <algorithm>

using namespace std;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

void query(const string& type, int x, int y) {
    cout << type << " " << x << " " << y << endl;
    cout.flush();
}

int read() {
    int res;
    cin >> res;
    return res;
}

int main() {
    int n;
    cin >> n;

    vector<int> factors;

    auto check_factor = [&](int p) {
        if (p == 1) return false;
        query("/", 1, p);
        int res = read();
        if (res == -1) {
            factors.push_back(p);
            return true;
        }
        return false;
    };

    auto find_factor = [&]() {
        while (true) {
            int a;
            do {
                a = rng() % (n - 1) + 1;
            } while (a == 1);

            query("^", a, (n + 1) / 4);
            int x = read();
            if (x == 0 || x == 1) continue;

            query("-", x, 1);
            int y = read();
            if (!check_factor(y)) {
                query("+", x, 1);
                y = read();
                check_factor(y);
            }
            break;
        }
    };

    while (factors.size() < 10) {
        find_factor();
        if (factors.size() == 1) {
            int p = factors[0];
            query("/", n, p);
            int q = read();
            factors.push_back(q);
        }
        if (factors.size() >= 2) {
            sort(factors.begin(), factors.end());
            factors.erase(unique(factors.begin(), factors.end()), factors.end());
            if (factors.size() == 2) {
                int p = factors[0];
                int q = factors[1];
                query("*", p, q);
                int product = read();
                if (product == n) break;
            }
        }
    }

    cout << "!";
    for (int p : factors) {
        cout << " " << p;
    }
    cout << endl;
}

