vector<int> adj[905];
int n, m;

bool dfs(int u, int p, vector<int>& path) {
    path.push_back(u);
    if (u == n) return true;
    for (int v : adj[u]) {
        if (v != p) {
            if (dfs(v, u, path)) return true;
        }
    }
    path.pop_back();
    return false;
}

bool has_second_path(int u, int p) {
    int deg = 0;
    for (int v : adj[u]) if (v != p) deg++;
    if (deg > 1) return true;
    for (int v : adj[u]) {
        if (v != p) {
            vector<int> path;
            dfs(v, u, path);
            for (int x : path) {
                int cnt = 0;
                for (int w : adj[x]) if (w != p) cnt++;
                if (cnt > 1) return true;
            }
        }
    }
    return false;
}

