int n, m;
vector<vector<int>> adj;
int t[100005], ans[100005], cnt[100005], dis[100005];

void dfs(int u, int p) {
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs(v, u);
        cnt[u] += cnt[v];
    }
    cnt[u] += 1;
}

void imp(int u) {
    if (dis[u] > t[u]) {
        ans[m]++;
        dis[u] = 0;
    } else if (dis[u] == t[u]) {
        ans[m]--;
        dis[u] = 0;
    }
}

void update(int u, int p, int v) {
    if (u == 0) return;
    dis[u] += v;
    imp(u);
    update(p, adj[p][0] == u ? adj[p][1] : adj[p][0], v);
}

int main() {
