    for (int i = 1; i <= m; ++i) {
        int x;
        cin >> x;
        if (x > 0) {
            update(x, adj[x].size() ? adj[x][0] : 0, -1);
        } else {
            update(-x, adj[-x].size() ? adj[-x][0] : 0, 1);
        }
        if (i > 1) ans[i] = ans[i - 1];
    }
    for (int i = 1; i <= m; ++i) cout << ans[i] << " \n"[i == m];
}

