using namespace std;

int largestRectangleArea(const vector<int>& heights) {
    stack<int> stack;
    int maxArea = 0;
    int n = heights.size();
    for (int i = 0; i <= n; ++i) {
        while (!stack.empty() && (i == n || heights[stack.top()] >= heights[i])) {
            int h = heights[stack.top()];
            stack.pop();
            int width = stack.empty() ? i : i - stack.top() - 1;
            maxArea = max(maxArea, width * h);
        }
