const int OO = 1e9;
const int MAXN = 65;
const int MAXM = 65;
const int MAXR = 100005;

int n, m, r;
int dist[MAXN][MAXN];
int cars[MAXM][MAXN][MAXN];
int dp[MAXN][MAXM];

void floyd_warshall() {
    for (int k = 1; k <= n; k++) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

void precalculate(int k) {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            dp[i][j] = OO;
        }
    }
    for (int c = 1; c <= m; c++) {
        for (int i = 1; i <= n; i++) {
            dp[i][c] = min(dp[i][c], cars[c][i][i]);
        }
    }
    for (int t = 1; t <= k; t++) {
        for (int u = 1; u <= n; u++) {
            for (int v = 1; v <= n; v++) {
                for (int c = 1; c <= m; c++) {
                    dp[u][c] = min(dp[u][c], dp[v][c] + dist[u][v]);
                }
            }
            for (int u = 1; u <= n; u++) {
                for (int v = 1; v <= n; v++) {
                    for (int c1 = 1; c1 <= m; c1++) {
                        for (int c2 = 1; c2 <= m; c2++) {
                            dp[u][c2] = min(dp[u][c2], dp[v][c1] + cars[c2][u][v]);
                        }
                    }
                }
            }
        }
    }
}

