            for(int j=1;j<=n;j++){
                cin >> cars[c][i][j];
            }
        }
    }
    memset(dist, OO, sizeof(dist));
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++){
            dist[i][j] = cars[1][i][j];
        }
    }
    floyd_warshall();

    while(r--){
        int s, t, k;
        cin >> s >> t >> k;
        precalculate(k);
        int ans = OO;
        for(int c=1;c<=m;c++){
            ans = min(ans, dp[s][c] + cars[c][s][t]);
        }
        cout << ans << "\n";
    }
}

