    ld time_cooked = 0;
    while (time_cooked < t) {
        if (time_cooked + d <= t) {
            if (time_cooked + k < time_cooked + d) {
                ld cooking_time = k;
                time_cooked += cooking_time;
                total_time += cooking_time;
            } else {
                ld cooking_time = d - time_cooked;
                time_cooked += cooking_time;
