    for(int k = 1; k <= (n+1)/2; ++k){
        string new_s = s.substr(k-1) + "#" + s.substr(0, n-k+1);
        vector<int> z = z_function(new_s);
        int max_odd = -1;
        for(int i = k+1; i < new_s.size(); ++i){
            if(i + z[i] == new_s.size() && z[i] % 2 == 1 && z[i] > max_odd){
                max_odd = z[i];
            }
        }
        ans[k-1] = max_odd;
    }
    for(int i = 0; i < n/2; ++i){
        cout << ans[i] << " ";
    }
    cout << ans[n/2] << "\n";
}

