#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

struct TrieNode {
    TrieNode* children[26];
    int index;
    TrieNode() : index(-1) {
        memset(children, 0, sizeof(children));
    }
};

void insert(TrieNode* root, const string& s, int idx) {
    TrieNode* node = root;
    for (char c : s) {
        if (!node->children[c - 'a']) {
            node->children[c - 'a'] = new TrieNode();
        }
        node = node->children[c - 'a'];
    }
    node->index = idx;
}

vector<int> findPrefixes(const string& t, TrieNode* root) {
    vector<int> result;
    int n = t.size();
    for (int i = 0; i < n; ++i) {
        TrieNode* node = root;
        for (int j = i; j < n; ++j) {
            char c = t[j];
            if (node->children[c - 'a']) {
                node = node->children[c - 'a'];
                if (node->index != -1) {
                    result.push_back(node->index);
                }
            } else {
                break;
            }
        }
    }
    return result;
}

int main() {
    int N;
    cin >> N;
    vector<string> S(N);
    TrieNode* root = new TrieNode();
    for (int i = 0; i < N; ++i) {
        cin >> S[i];
        insert(root, S[i], i);
    }
    string t;
    cin >> t;
    vector<int> prefixes = findPrefixes(t, root);
    int m = t.size();
    vector<long long> dp(m + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < prefixes.size(); ++j) {
            if (i + 1 >= S[prefixes[j]].size()) {
                int k = i + 1 - S[prefixes[j]].size();
                if (t.substr(k, S[prefixes[j]].size()) == S[prefixes[j]]) {
                    dp[i + 1] = (dp[i + 1] + dp[k]) % MOD;
                }
            }
        }
    }
    cout << dp[m] << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAXN = 6005;

int N, K;
ll x[MAXN], y[MAXN];
vector<int> ans;

bool valid(int mask) {
    for(int i = 0; i < N; i++){
        for(int j = i + 1; j < N; j++){
            if((mask & (1 << i)) && (mask & (1 << j))){
                ll dx = x[i] - x[j];
                ll dy = y[i] - y[j];
                if(dx * dx + dy * dy < 4){
                    return false;
                }
            }
        }
    }
    return true;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> K;
    for(int i = 1; i <= N; i++){
        cin >> x[i] >> y[i];
    }
    int lim = 1 << N;
    int best_mask = -1;
    for(int mask = 0; mask < lim; mask++){
        if(__builtin_popcount(mask) == K && valid(mask)){
            if(best_mask == -1 || mask < best_mask){
                best_mask = mask;
            }
        }
    }
    if(best_mask == -1){
        cout << -1;
    } else {
        for(int i = 1; i <= N; i++){
            if(best_mask & (1 << i)){
                ans.push_back(i);
            }
        }
        for(int a : ans){
            cout << a << "\n";
        }
    }
}

