vector<vector<int>> adj;
vector<bool> visited;
vector<int> path;
int k, found_cycle = 0;

void dfs(int u, int p) {
    if (found_cycle) return;
    visited[u] = true;
    path.push_back(u);
    for (int v : adj[u]) {
        if (v == p) continue;
        if (visited[v]) {
            int index = find(path.begin(), path.end(), v) - path.begin();
            if (path.size() - index >= k + 1) {
                found_cycle = 1;
                path.erase(path.begin(), path.begin() + index);
                return;
            }
        } else {
            dfs(v, u);
        }
    }
    if (!found_cycle) path.pop_back();
}

