            for (int i = 0; i < 4; i++){
                if (mask & (1 << i)){
                    current[i] = rotate90ccw(current[i], centers[i]);
                    moves++;
                }
                if (mask & (2 << i)){
                    current[i] = rotate90ccw(current[i], centers[i]);
                    current[i] = rotate90ccw(current[i], centers[i]);
                    moves += 2;
                }
                if (mask & (4 << i)){
                    current[i] = rotate90ccw(current[i], centers[i]);
                    current[i] = rotate90ccw(current[i], centers[i]);
                    current[i] = rotate90ccw(current[i], centers[i]);
                    moves += 3;
                }
            }
