                num = (num * 10 + s[l-1] - '0') % MOD;
                if(s[l-1] != '0' || l == i){
                    dp[i][j] = (dp[i][j] + (j > 0 ? dp[l-1][j-1] : 0) * num) % MOD;
                }
            }
        }
    }

    cout << dp[n][k];
}

