#include <bits/stdc++.h>
using namespace std;

int dx[] = {1, 0, 0};
int dy[] = {0, 1, 0};
int dz[] = {0, 0, 1};

bool inBounds(int x, int y, int z, int n, int m, int k) {
    return x >= 0 && x < n && y >= 0 && y < m && z >= 0 && z < k;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<vector<char>>> grid(n, vector<vector<char>>(m, vector<char>(k)));
    vector<vector<vector<int>>> indegree(n, vector<vector<int>>(m, vector<int>(k, 0)));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int l = 0; l < k; ++l) {
                cin >> grid[i][j][l];
                if (grid[i][j][l] == '1') {
                    for (int dir = 0; dir < 3; ++dir) {
                        int nx = i + dx[dir];
                        int ny = j + dy[dir];
                        int nz = l + dz[dir];
                        if (inBounds(nx, ny, nz, n, m, k) && grid[nx][ny][nz] == '1') {
                            indegree[nx][ny][nz]++;
                        }
                    }
                }
            }
        }
        cin.ignore();
    }

    queue<tuple<int, int, int>> q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int l = 0; l < k; ++l) {
                if (grid[i][j][l] == '1' && indegree[i][j][l] == 0) {
                    q.emplace(i, j, l);
                }
            }
        }
    }

    vector<vector<vector<bool>>> reachable(n, vector<vector<bool>>(m, vector<bool>(k, false)));
    while (!q.empty()) {
        auto [x, y, z] = q.front();
        q.pop();
        reachable[x][y][z] = true;
        for (int dir = 0; dir < 3; ++dir) {
            int nx = x - dx[dir];
            int ny = y - dy[dir];
            int nz = z - dz[dir];
            if (inBounds(nx, ny, nz, n, m, k) && grid[nx][ny][nz] == '1') {
                indegree[nx][ny][nz]--;
                if (indegree[nx][ny][nz] == 0) {
                    q.emplace(nx, ny, nz);
                }
            }
        }
    }

    vector<vector<vector<vector<bool>>>> canReach(n, vector<vector<vector<bool>>>(m, vector<vector<bool>>(k, vector<bool>(n * m * k, false))));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int l = 0; l < k; ++l) {
                if (grid[i][j][l] == '1' && indegree[i][j][l] == 0) {
                    queue<tuple<int, int, int>> q;
                    q.emplace(i, j, l);
                    while (!q.empty()) {
                        auto [x, y, z] = q.front();
                        q.pop();
                        int idx = x * m * k + y * k + z;
                        canReach[i][j][l][idx] = true;
                        for (int dir = 0; dir < 3; ++dir) {
                            int nx = x + dx[dir];
                            int ny = y + dy[dir];
                            int nz = z + dz[dir];
                            if (inBounds(nx, ny, nz, n, m, k) && grid[nx][ny][nz] == '1') {
                                indegree[nx][ny][nz]--;
                                int nidx = nx * m * k + ny * k + nz;
                                if (indegree[nx][ny][nz] == 0) {
                                    q.emplace(nx, ny, nz);
                                }
                                canReach[i][j][l][nidx] = true;
                            }
                        }
                    }
                }
            }
        }
    }

    int critical = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int l = 0; l < k; ++l) {
                if (grid[i][j][l] == '1') {
                    vector<int> canReachAfterFail;
                    for (int x = 0; x < n; ++x) {
                        for (int y = 0; y < m; ++y) {
                            for (int z = 0; z < k; ++z) {
                                if (grid[x][y][z] == '1' && (x != i || y != j || z != l)) {
                                    indegree[x][y][z] -= canReach[x][y][z][i * m * k + j * k + l];
                                    if (indegree[x][y][z] == 0) {
                                        canReachAfterFail.push_back(x * m * k + y * k + z);
                                    }
                                }
                            }
                        }
                    }

                    queue<tuple<int, int, int>> q;
                    for (auto& idx : canReachAfterFail) {
                        int x = idx / (m * k);
                        int y = (idx / k) % m;
                        int z = idx % k;
                        q.emplace(x, y, z);
                    }

                    vector<vector<vector<bool>>> reachableAfterFail(n, vector<vector<bool>>(m, vector<bool>(k, false)));

                    while (!q.empty()) {
                        auto [x, y, z] = q.front();
                        q.pop();
                        reachableAfterFail[x][y][z] = true;
                        for (int dir = 0; dir < 3; ++dir) {
                            int nx = x + dx[dir];
                            int ny = y + dy[dir];
                            int nz = z + dz[dir];
                            if (inBounds(nx, ny, nz, n, m, k) && grid[nx][ny][nz] == '1') {
                                indegree[nx][ny][nz]--;
                                if (indegree[nx][ny][nz] == 0) {
                                    q.emplace(nx, ny, nz);
                                }
                            }
                        }
                    }

                    bool isCritical = false;
                    for (int x = 0; x < n; ++x) {
                        for (int y = 0; y < m; ++y) {
                            for (int z = 0; z < k; ++z) {
                                if (grid[x][y][z] == '1' && reachable[x][y][z] && !reachableAfterFail[x][y][z]) {
                                    isCritical = true;
                                    break;
                                }
                            }
                            if (isCritical) break;
                        }
                        if (isCritical) break;
                    }

                    if (isCritical) {
                        critical++;
                    }

                    for (int x = 0; x < n; ++x) {
                        for (int y = 0; y < m; ++y) {
                            for (int z = 0; z < k; ++z) {
                                if (grid[x][y][z] == '1' && (x != i || y != j || z != l)) {
                                    indegree[x][y][z] += canReach[x][y][z][i * m * k + j * k + l];
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    cout << critical;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int N = 3005;
int dist[N][N];

void floyd_warshall(int n) {
    for (int k = 1; k <= n; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++){
            if(i==j) dist[i][j] = 0;
            else dist[i][j] = INF;
        }
    }
    for(int i=0;i<m;i++){
        int u, v;
        cin >> u >> v;
        dist[u][v] = 1;
    }
    floyd_warshall(n);
    int max_dist = -1;
    vector<int> best_tour;
    for(int a=1;a<=n;a++){
        for(int b=1;b<=n;b++){
            if(a==b) continue;
            for(int c=1;c<=n;c++){
                if(c==a || c==b) continue;
                for(int d=1;d<=n;d++){
                    if(d==a || d==b || d==c) continue;
                    int current_dist = dist[a][b] + dist[b][c] + dist[c][d];
                    if(current_dist > max_dist){
                        max_dist = current_dist;
                        best_tour = {a, b, c, d};
                    }
                }
            }
        }
    }
    for(auto city : best_tour){
        cout << city << " ";
    }
    cout << "\n";
}

