bool can_eat(vector<long long>& q, deque<pair<int, long long>>& rem) {
    while (!rem.empty()) {
        if (q.front() > rem.front().second) {
            q.front() += rem.front().second;
            rem.pop_front();
        } else if (q.back() > rem.back().second) {
            q.back() += rem.back().second;
            rem.pop_back();
        } else {
            return false;
        }
    }
    return true;
}

